static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0) return timeBucket;
    int year = (int)(timeBucket / 10000L);
    int monthDay = (int)(timeBucket % 10000L);
    int month = monthDay / 100;
    int day = monthDay % 100;
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0 || index >= str.length() || index < 0) {
        return 0;
    }
    int end = Math.min(str.length(), index + len);
    int byteCount = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(ch) && i + 1 < end &&
            Character.isLowSurrogate(str.charAt(i + 1))) {
            codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
            i++; // skip low surrogate
        } else {
            codePoint = ch;
        }
        if (codePoint <= 0x7F) {
            byteCount += 1;
        } else if (codePoint <= 0x7FF) {
            byteCount += 2;
        } else if (codePoint <= 0xFFFF) {
            byteCount += 3;
        } else {
            byteCount += 4;
        }
    }
    return byteCount;
}

