public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || str.length() == 0) {
        return lb;
    }
    int len = str.length();
    // Allocate maximum possible size (4 bytes per char)
    byte[] out = new byte[len * 4];
    int outPos = 0;
    for (int i = 0; i < len; ) {
        int cp = Character.codePointAt(str, i);
        if (cp < 0x80) {                      // 1 byte
            out[outPos++] = (byte) cp;
        } else if (cp < 0x800) {              // 2 bytes
            out[outPos++] = (byte) (0xC0 | (cp >> 6));
            out[outPos++] = (byte) (0x80 | (cp & 0x3F));
        } else if (cp < 0x10000) {            // 3 bytes
            out[outPos++] = (byte) (0xE0 | (cp >> 12));
            out[outPos++] = (byte) (0x80 | ((cp >> 6) & 0x3F));
            out[outPos++] = (byte) (0x80 | (cp & 0x3F));
        } else {                              // 4 bytes
            out[outPos++] = (byte) (0xF0 | (cp >> 18));
            out[outPos++] = (byte) (0x80 | ((cp >> 12) & 0x3F));
            out[outPos++] = (byte) (0x80 | ((cp >> 6) & 0x3F));
            out[outPos++] = (byte) (0x80 | (cp & 0x3F));
        }
        i += Character.charCount(cp);
    }
    // Write the encoded bytes into the linked buffer
    // Assume LinkedBuffer has a write(byte[], int, int) method
    if (outPos > 0) {
        lb.write(out, 0, outPos);
    }
    return lb;
}

