private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null) {
        return suffix == null;
    }
    if (suffix == null) {
        return false;
    }
    if (ignoreCase) {
        int suffixLen = suffix.length();
        if (suffixLen > str.length()) {
            return false;
        }
        return str.regionMatches(true, str.length() - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present for absolute paths
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String value = part;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

