public static int nextPrime(int desiredCapacity) {
    int min = Math.max(2, desiredCapacity);
    int candidate = min;
    if (candidate % 2 == 0 && candidate != 2) candidate++;
    int limit = desiredCapacity >= 1000 ? (int) Math.ceil(desiredCapacity * 1.11) : Integer.MAX_VALUE;
    while (candidate <= limit) {
        boolean prime = true;
        if (candidate == 2) return candidate;
        if (candidate % 2 == 0) prime = false;
        if (prime) {
            for (int i = 3; i * i <= candidate; i += 2) {
                if (candidate % i == 0) {
                    prime = false;
                    break;
                }
            }
        }
        if (prime) return candidate;
        candidate += (candidate == 2 ? 1 : 2);
    }
    while (true) {
        boolean prime = true;
        if (candidate == 2) return candidate;
        if (candidate % 2 == 0) prime = false;
        if (prime) {
            for (int i = 3; i * i <= candidate; i += 2) {
                if (candidate % i == 0) {
                    prime = false;
                    break;
                }
            }
        }
        if (prime) return candidate;
        candidate++;
    }
}

