private JsonObject convertProperties(List<KeyStringValuePair> properties){
    JsonObject json = new JsonObject();
    if (properties == null){
        return json;
    }
    for (KeyStringValuePair kv : properties) {
        if (kv == null){
            continue;
        }
        String key = kv.getKey();
        Object value = kv.getValue();
        if (key == null){
            continue;
        }
        if (value == null){
            json.add(key, JsonNull.INSTANCE);
        } else if (value instanceof Number) {
            json.addProperty(key, (Number) value);
        } else if (value instanceof Boolean) {
            json.addProperty(key, (Boolean) value);
        } else if (value instanceof String) {
            json.addProperty(key, (String) value);
        } else if (value instanceof JsonElement) {
            json.add(key, (JsonElement) value);
        } else {
            json.addProperty(key, value.toString());
        }
    }
    return json;
}

protected int removeUnusedNodes() {
    int removed = 0;
    if (root == null) {
        return 0;
    }
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category node = stack.pop();
        List<Category> children = node.getChildren();
        if (children != null) {
            Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) {
                    it.remove();          // remove inactive node
                    removed++;             // count removed node
                } else {
                    stack.push(child);     // keep exploring active nodes
                }
            }
        }
    }
    return removed;
}

