final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Find the start offset of the constant pool entry
    int offset = constantPoolStart; // (Assumes this is a field pointing to the start of the constant pool)
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            case 3:
            case 4:
            case 7:
            case 8:
            case 9:
            case 10:
            case 11:
            case 12:
                offset += 4;
                break;
            case 5:
            case 6:
                offset += 8;
                i++; // these consume two indices
                break;
            default:
                // Unknown tag, just skip (should not happen)
                break;
        }
    }
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException(
                "Constant pool entry " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) | (classFileBuffer[offset + 2] & 0xFF);
    int start = offset + 3;

    if (charBuffer != null && charBuffer.length >= length) {
        // Decode modified UTF-8 directly into the provided char buffer
        int end = start + length;
        int cpCount = 0;
        for (int pos = start; pos < end; pos++) {
            int b = classFileBuffer[pos] & 0xFF;
            if (b >> 7 == 0) {
                charBuffer[cpCount++] = (char) b;
            } else if ((b >> 5) == 0b110) {
                int b2 = classFileBuffer[++pos] & 0xFF;
                charBuffer[cpCount++] = (char) (((b & 0x1F) << 6) | (b2 & 0x3F));
            } else if ((b >> 4) == 0b1110) {
                int b2 = classFileBuffer[++pos] & 0xFF;
                int b3 = classFileBuffer[++pos] & 0xFF;
                charBuffer[cpCount++] = (char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
            } else {
                // For simplicity, skip any unexpected byte patterns
                cpCount++;
            }
        }
        return new String(charBuffer, 0, cpCount);
    } else {
        // Fall back to String constructor with UTF-8 charset
        return new String(classFileBuffer, start, length,
                java.nio.charset.StandardCharsets.UTF_8);
    }
}

