private void check(String modelName) throws IllegalStateException {
    try {
        Class<?> clazz = Class.forName(modelName);
        int expectedIndex = 0;
        java.util.List<java.lang.reflect.Field> shardingFields = new java.util.ArrayList<>();
        for (java.lang.reflect.Field field : clazz.getDeclaredFields()) {
            if (field.isAnnotationPresent(com.example.ShardingKey.class)) {
                shardingFields.add(field);
            }
        }
        shardingFields.sort(java.util.Comparator.comparingInt(f -> f.getAnnotation(com.example.ShardingKey.class).value()));
        for (java.lang.reflect.Field field : shardingFields) {
            int idx = field.getAnnotation(com.example.ShardingKey.class).value();
            if (idx != expectedIndex) {
                throw new IllegalStateException("Sharding key indices are not continuous in " + modelName);
            }
            expectedIndex++;
        }
    } catch (ClassNotFoundException e) {
        throw new IllegalStateException("Model class not found: " + modelName, e);
    }
}

