private void pop(final String descriptor){
    int i = 0;
    final int len = descriptor.length();
    // If we have a method descriptor, skip the '(' and pop until ')'
    if (i < len && descriptor.charAt(i) == '(') {
        i++; // skip '('
        while (i < len && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                // Object type; skip until ';'
                i++;
                while (i < len && descriptor.charAt(i) != ';') i++;
                i++; // skip ';'
                pos--; // pop one slot
            } else if (c == '[') {
                // Array type; skip the component type
                i++;
                while (i < len) {
                    char d = descriptor.charAt(i);
                    if (d == 'L') {
                        i++;
                        while (i < len && descriptor.charAt(i) != ';') i++;
                        i++; // skip ';'
                        break;
                    } else if (d == '[') {
                        i++; // another dimension
                    } else {
                        i++; // primitive type
                        break;
                    }
                }
                pos--; // array occupies one slot
            } else {
                // Primitive type
                if (c == 'J' || c == 'D') {
                    pos -= 2; // long/double occupy two slots
                } else if (c != 'V') {
                    pos--; // other primitives occupy one slot
                }
                i++;
            }
        }
    } else {
        // Descriptor is a single type (not a method)
        while (i < len) {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                i++;
                while (i < len && descriptor.charAt(i) != ';') i++;
                i++;
                pos--;
            } else if (c == '[') {
                i++;
                while (i < len) {
                    char d = descriptor.charAt(i);
                    if (d == 'L') {
                        i++;
                        while (i < len && descriptor.charAt(i) != ';') i++;
                        i++;
                        break;
                    } else if (d == '[') {
                        i++;
                    } else {
                        i++;
                        break;
                    }
                }
                pos--;
            } else {
                if (c == 'J' || c == 'D') {
                    pos -= 2;
                } else if (c != 'V') {
                    pos--;
                }
                i++;
            }
        }
    }
}

