public int readTag() throws IOException {
    if (pos == count) {
        return 0;
    }
    int tag = 0;
    for (int shift = 0; shift < 32; shift += 7) {
        if (pos == count) {
            return 0;
        }
        byte b = buf[pos++];
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
    }
    throw new IOException("Tag is too long");
}

